<?php

defined('ABSPATH') || exit;

final class PLDR_Future_Corpus {
    public static function manifest(int $edition_id):array { $edition=PLDR_Future_Data::require_edition($edition_id);if(is_wp_error($edition))return array('error'=>$edition);$doc=PLDR_Core::document((int)$edition['document_id']);if(!$doc)return array('error'=>PLDR_Core::machine_error('pldr_corpus_document','Document not found.',404));if('patient-cases'===$doc['category']&&!apply_filters('pldr_ai_patient_case_allowed',false,$edition_id,$doc))return array('error'=>PLDR_Core::machine_error('pldr_corpus_patient_case','Patient-case documents are excluded from AI corpus manifests unless separately approved.',403));$allowed=apply_filters('pldr_ai_corpus_allowed',false,$edition_id,$edition,$doc);if(!$allowed)return array('error'=>PLDR_Core::machine_error('pldr_corpus_not_allowed','This edition is not allowlisted for AI corpus use.',403));$chunks=array();foreach(PLDR_Future_Data::ocr_pages($edition_id) as $row){$text=trim((string)$row['text_content']);if(''===$text)continue;$chunks[]=array('chunk_id'=>'f12:'.$edition['public_id'].':e'.$edition_id.':p'.(int)$row['page_number'],'page'=>(int)$row['page_number'],'citation_anchor'=>PLDR_Reader::citation($edition,(int)$row['page_number'],'sabri'),'rights'=>(string)$edition['rights_basis'],'quality'=>(float)$row['quality_score'],'text_sha256'=>hash('sha256',$text),'retrieval_url'=>rest_url('pldr/v1/future/reflow/'.$edition_id.'?page='.(int)$row['page_number']));if(count($chunks)>=10000)break;}return array('manifest_version'=>'1.0','owner'=>'File 12','consumer'=>'File 16 only through approved contract','document_id'=>$edition['public_id'],'edition_id'=>$edition_id,'rights'=>(string)$edition['rights_basis'],'license'=>(string)$edition['license_code'],'entitlement_rechecked'=>true,'chunks'=>$chunks,'contains_text'=>false,'diagnosis_or_prescription_authority'=>false); }
}
